import garb from './assets/garb.svg';
import pencil from './assets/pencil.svg';
import { useState } from 'react';
// TaskList takes tasks and displays them
const TaskList = ({ tasks, deleteTask, setTas}) => {
  const [editTaskID, setEditTaskID] = useState(null);
  const [editTaskName, setEditTaskName] = useState("");
  const [editTaskDesc, setEditTaskDesc] = useState("");

  const handleEditTask = (task) => {
    setEditTaskID(task.id);
    setEditTaskName(task.name);
    setEditTaskDesc(task.desc || "");
  };

  const updateTask = (id, updatedTask) => {
    setTasks((prevTasks) =>
      prevTasks.map((task) =>
        task.id === id ? { ...task, ...updatedTask } : task
      )
    );
  };

  const handleSaveTask = (id) => {
    updateTask(id, { name: editTaskName, desc: editTaskDesc });
    setEditTaskID(null);
  };
    return (
      <div className="taskDisplayContainer w-full space-y-4 max-h-[400px] overflow-y-auto">
        {tasks.map((task, index) => (
          <div
            className="taskDisplay relative py-2 flex flex-col items-center justify-center w-full font-normal border-b border-white last:border-none"
            key={task.id}
          >
            <div className="flex justify-end w-full space-x-2 px-4">
              <img
                className="w-6 h-6 rounded-lg hover:scale-110 transition duration-100 ease-in-out cursor-pointer"
              onClick={() => handleEditTask(task)}
                src={pencil}
                alt="edit task"
              />
              <img
                className="w-6 h-6 rounded-lg hover:scale-110 transition duration-100 ease-in-out cursor-pointer"
                onClick={() => deleteTask(task.id)}
                src={garb}
                alt="delete task"
              />
            </div>
            {editTaskID === task.id ? (
              <>
                <input
                  className="whitespace-normal break-words w-full text-white text-3xl sm:text-2xl font-normal py-2 px-4 text-left bg-transparent border-none focus:ring-0 focus:outline-none"
                  type="text"
                  value={editTaskName}
                  onChange={(e) => setEditTaskName(e.target.value)}
                />
                <textarea
                  className="whitespace-normal break-words w-full text-white sm:text-lg font-normal py-2 px-4 text-left bg-transparent border-none focus:ring-0 focus:outline-none"
                  value={editTaskDesc}
                  onChange={(e) => setEditTaskDesc(e.target.value)}
                />
                <button
                  className="mt-2 px-4 py-1 bg-white text-black rounded-lg hover:opacity-80 transition"
                  onClick={() => handleSaveTask(task.id)}
                >
                  Save
                </button>
              </>
            ) : (
              <>
                <h1 className="whitespace-normal break-words w-full text-white text-3xl sm:text-2xl font-normal py-2 px-4 text-left">
                  {task.name}
                </h1>
                {task.desc && (
                  <p className="whitespace-normal break-words w-full text-white sm:text-lg font-normal py-2 px-4 text-left">
                    {task.desc}
                  </p>
                )}
              </>
            )}
          </div>
        ))}
      </div>
    );
};

export default TaskList;
